static const int OFFSET = 10000;
static const int TAPE_SIZE = 50000;
static char tape[TAPE_SIZE];

int solve_case(const vector<int>& nums) {
    memset(tape, 0, sizeof(tape));
    int pos = OFFSET;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i > 0) pos++;
        for (int k = 0; k < nums[i]; ++k) {
            tape[pos++] = 1;
        }
    }
    int head = OFFSET;
    int state = 0;
    while (state != 2451) {
        uint16_t v = (tape[head] == 0) ? T0[state] : T1[state];
        tape[head] = v & 1;
        head += (v & 2) ? 1 : -1;
        state = v >> 2;
    }
    return head - OFFSET;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;
    string line;
    getline(cin, line); // consume newline

    for (int t = 0; t < N; ++t) {
        if (!getline(cin, line)) break;
        while (line.empty() && cin) {
            getline(cin, line);
        }
        stringstream ss(line);
        vector<int> nums;
        int val;
        while (ss >> val) {
            nums.push_back(val);
        }
        cout << solve_case(nums) << "\n";
    }
    return 0;
}
